export type Post = {
  id: string
  title: string
  createdAt: string
}

const posts: Post[] = []

export function listPosts(): Post[] {
  return [...posts]
}

export function addPost(title: string): Post {
  const post: Post = {
    id: crypto.randomUUID(),
    title: title.trim(),
    createdAt: new Date().toISOString(),
  }
  posts.push(post)
  return post
}

